const generateMockRelations = (): BilateralSentimentData[] => {
  const relations: BilateralSentimentData[] = [];
  for (let i = 0; i < COUNTRIES.length; i++) {
    for (let j = i + 1; j < COUNTRIES.length; j++) {
      const a = COUNTRIES[i],
        b = COUNTRIES[j];
      const sameBlock = a.block === b.block;
      const baseAffinity = sameBlock ? 0.3 + Math.random() * 0.5 : -0.4 + Math.random() * 0.6;
      const interactions = Math.floor(Math.random() * 200) + 10;
      relations.push({
        from_country: a.id,
        to_country: b.id,
        affinity_score: Math.max(-1, Math.min(1, baseAffinity)),
        sentiment_avg: baseAffinity * 0.8 + (Math.random() - 0.5) * 0.3,
        interaction_count: interactions,
        risk_score: (a.risk + b.risk) / 2 + (sameBlock ? -1 : 2) + Math.random() * 2,
        last_updated: new Date(Date.now() - Math.random() * 1e10).toISOString(),
      } as BilateralSentimentData);
    }
  }
  return relations;
};

const generateTimeline = (): PanelTimelineEntry[] => {
  return Array.from({ length: 12 }, (_, i) => ({
