    date: `202${4 + Math.floor(i / 12)}-${String((i % 12) + 1).padStart(2, '0')}-15`,
    title: `BM Genel Kurul ${i + 1}. Olağan Oturum`,
    speaker_count: Math.floor(Math.random() * 50) + 30,
    segment_count: Math.floor(Math.random() * 300) + 100,
  }));
};

// ─── D3 HOOK ─────────────────────────────────────────────────────
const useD3 = (
  renderFn: (
    svg: d3.Selection<SVGSVGElement, unknown, null, undefined>,
    width: number,
    height: number,
  ) => void,
  deps: any[],
) => {
  const ref = useRef<SVGSVGElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ref.current || !containerRef.current) return;
    const { width, height } = containerRef.current.getBoundingClientRect();
    const svg = d3.select(ref.current);
    svg.selectAll('*').remove();
    svg.attr('width', width).attr('height', height);
    renderFn(svg, width, height);
  }, deps);

  return { ref, containerRef };
};

// ─── GLOBE VIEW ──────────────────────────────────────────────────
const GlobeView = ({
  data,
  onSelect,
}: {
  data: BilateralSentimentData[];
  onSelect: (c: string) => void;
}) => {
  const { ref, containerRef } = useD3(
    (svg, w, h) => {
      const projection = d3
        .geoOrthographic()
        .scale(Math.min(w, h) / 2.8)
        .translate([w / 2, h / 2]);
      const path = d3.geoPath().projection(projection);
      const g = svg.append('g');

      // Sphere
      g.append('path')
        .datum({ type: 'Sphere' } as any)
        .attr('fill', '#0f172a')
        .attr('stroke', '#1e293b')
        .attr('stroke-width', 1.5)
        .attr('d', path as any);

      // Graticule
      const graticule = d3.geoGraticule();
      g.append('path')
        .datum(graticule() as any)
        .attr('fill', 'none')
        .attr('stroke', '#1e293b')
        .attr('stroke-width', 0.5)
        .attr('d', path as any);

      // Country points
      const countryMap = new Map(COUNTRIES.map((c) => [c.id, c]));
      const affinityScale = d3.scaleSequential(d3.interpolateRdYlGn).domain([-1, 1]);

      COUNTRIES.forEach((c) => {
        const [x, y] = projection([c.lon, c.lat]) || [0, 0];
        if (x === 0 && y === 0) return;

        const circle = g
          .append('circle')
          .attr('cx', x)
          .attr('cy', y)
          .attr('r', 4 + c.power * 0.8)
          .attr('fill', '#3b82f6')
          .attr('stroke', '#60a5fa')
          .attr('stroke-width', 1.5)
          .attr('opacity', 0.9)
          .style('cursor', 'pointer');

        circle.append('title').text(`${c.name} | Güç: ${c.power} | Blok: ${c.block}`);

        circle.on('click', () => onSelect(c.id));
      });

      // Relations as arcs
      data.forEach((r) => {
        const from = countryMap.get(r.from_country);
        const to = countryMap.get(r.to_country);
        if (!from || !to) return;

        const f = projection([from.lon, from.lat]);
        const t = projection([to.lon, to.lat]);
        if (!f || !t) return;

        const mid = [(f[0] + t[0]) / 2, (f[1] + t[1]) / 2 - 30];
        const line = d3.line()([f, mid as [number, number], t]);

        g.append('path')
          .attr('d', line)
          .attr('fill', 'none')
          .attr('stroke', affinityScale(r.affinity_score || 0))
          .attr('stroke-width', Math.max(0.5, (r.interaction_count || 0) / 50))
          .attr('opacity', 0.6)
          .attr('stroke-linecap', 'round');
      });

      // Rotation interaction
      const rotation = [0, 0];
      const drag = d3.drag().on('drag', (event) => {
        rotation[0] += event.dx * 0.3;
        rotation[1] -= event.dy * 0.3;
        projection.rotate(rotation);
        g.selectAll('path').attr('d', path as any);
        g.selectAll('circle')
          .attr('cx', (d: any) => {
            const c = COUNTRIES.find((x) => x.id === d?.id);
            return c ? (projection([c.lon, c.lat]) || [0, 0])[0] : 0;
          })
          .attr('cy', (d: any) => {
            const c = COUNTRIES.find((x) => x.id === d?.id);
            return c ? (projection([c.lon, c.lat]) || [0, 0])[1] : 0;
          });
      });
      svg.call(drag as any);
    },
    [data, onSelect],
  );

  return (
    <div
      ref={containerRef}
      className="w-full h-[500px] relative bg-carbon-950 rounded-none border border-carbon-700"
    >
      <svg ref={ref} className="w-full h-full" />
      <div className="absolute top-3 left-3 bg-carbon-900/90 border border-carbon-700 p-2 text-2xs text-carbon-300">
        <MousePointer2 className="w-3 h-3 inline mr-1" /> Sürükleyerek döndürün
      </div>
    </div>
  );
};

// ─── CHORD DIAGRAM ───────────────────────────────────────────────
const ChordView = ({ data }: { data: BilateralSentimentData[] }) => {
  const { ref, containerRef } = useD3(
    (svg, w, h) => {
      const size = Math.min(w, h);
      const outerRadius = size / 2 - 40;
      const innerRadius = outerRadius - 20;

      const countryIds = COUNTRIES.map((c) => c.id);
      const matrix = Array.from({ length: countryIds.length }, () =>
        new Array(countryIds.length).fill(0),
      );

      data.forEach((r) => {
        const i = countryIds.indexOf(r.from_country);
        const j = countryIds.indexOf(r.to_country);
        if (i >= 0 && j >= 0) {
          const val = Math.abs(r.affinity_score || 0) * (r.interaction_count || 0);
          matrix[i][j] = val;
          matrix[j][i] = val;
        }
      });

      const chord = d3.chord().padAngle(0.05).sortSubgroups(d3.descending);
      const chords = chord(matrix);

      const arc = d3.arc().innerRadius(innerRadius).outerRadius(outerRadius);
      const ribbon = d3.ribbon().radius(innerRadius);

      const color = d3.scaleOrdinal(d3.schemeTableau10);

      const g = svg.append('g').attr('transform', `translate(${w / 2},${h / 2})`);

      // Groups
      const group = g.append('g').selectAll('g').data(chords.groups).join('g');

      group
        .append('path')
        .attr('fill', (d: any) => color(d.index))
        .attr('stroke', '#0f172a')
        .attr('d', arc as any)
        .style('cursor', 'pointer')
        .append('title')
        .text((d: any) => `${COUNTRIES[d.index].name}: ${d.value.toFixed(0)} etkileşim`);

      // Labels
      group
        .append('text')
        .each((d: any) => {
          d.angle = (d.startAngle + d.endAngle) / 2;
        })
        .attr('dy', '0.35em')
        .attr(
          'transform',
          (d: any) => `
        rotate(${(d.angle * 180) / Math.PI - 90})
        translate(${outerRadius + 10})
        ${d.angle > Math.PI ? 'rotate(180)' : ''}
      `,
        )
        .attr('text-anchor', (d: any) => (d.angle > Math.PI ? 'end' : 'start'))
        .text((d: any) => COUNTRIES[d.index].id)
        .attr('fill', '#94a3b8')
        .attr('font-size', '9px')
        .attr('font-family', 'monospace');

      // Ribbons
      g.append('g')
        .attr('fill-opacity', 0.6)
        .selectAll('path')
        .data(chords)
        .join('path')
        .attr('fill', (d: any) => color(d.source.index))
        .attr('d', ribbon as any)
        .attr('stroke', '#0f172a')
        .attr('stroke-width', 0.5)
        .append('title')
        .text((d: any) => `${COUNTRIES[d.source.index].name} ↔ ${COUNTRIES[d.target.index].name}`);
    },
    [data],
  );

  return (
    <div
      ref={containerRef}
      className="w-full h-[500px] relative bg-carbon-950 rounded-none border border-carbon-700"
    >
      <svg ref={ref} className="w-full h-full" />
    </div>
  );
};

// ─── HEATMAP VIEW ────────────────────────────────────────────────
const HeatmapView = ({ data }: { data: BilateralSentimentData[] }) => {
  const { ref, containerRef } = useD3(
    (svg, w, h) => {
      const margin = { top: 60, right: 20, bottom: 80, left: 80 };
      const innerW = w - margin.left - margin.right;
      const innerH = h - margin.top - margin.bottom;

      const pairs = data.map((r) => `${r.from_country}-${r.to_country}`);
      const uniquePairs = Array.from(new Set(pairs)).slice(0, 20);
      const timePoints = generateTimeline().map((t) => t.date.slice(0, 7));

      const heatData: { pair: string; time: string; value: number }[] = [];
      uniquePairs.forEach((pair) => {
        timePoints.forEach((time) => {
          heatData.push({
            pair,
            time,
            value: Math.random() * 2 - 1,
          });
        });
      });

      const x = d3.scaleBand().range([0, innerW]).domain(timePoints).padding(0.05);
      const y = d3.scaleBand().range([0, innerH]).domain(uniquePairs).padding(0.05);
      const color = d3.scaleSequential(d3.interpolateRdYlGn).domain([-1, 1]);

      const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`);

      g.selectAll('rect')
        .data(heatData)
        .join('rect')
        .attr('x', (d) => x(d.time) || 0)
        .attr('y', (d) => y(d.pair) || 0)
        .attr('width', x.bandwidth())
        .attr('height', y.bandwidth())
        .attr('fill', (d) => color(d.value))
        .attr('rx', 2)
        .append('title')
        .text((d) => `${d.pair} @ ${d.time}: ${d.value.toFixed(2)}`);

      // Axes
      g.append('g')
        .attr('transform', `translate(0,${innerH})`)
        .call(d3.axisBottom(x).tickSize(0))
        .select('.domain')
        .remove();
      g.selectAll('.tick text')
        .attr('fill', '#64748b')
        .attr('font-size', '9px')
        .attr('transform', 'rotate(-45)')
        .attr('text-anchor', 'end');

      g.append('g').call(d3.axisLeft(y).tickSize(0)).select('.domain').remove();
      g.selectAll('.tick text').attr('fill', '#64748b').attr('font-size', '8px');
    },
    [data],
  );

  return (
    <div
      ref={containerRef}
      className="w-full h-[600px] relative bg-carbon-950 rounded-none border border-carbon-700 overflow-auto"
    >
      <svg ref={ref} className="w-full h-full" />
    </div>
  );
};

// ─── RADAR PROFILE ───────────────────────────────────────────────
const RadarProfile = ({ selectedCountry }: { selectedCountry: string | null }) => {
  const country = useMemo(() => COUNTRIES.find((c) => c.id === selectedCountry), [selectedCountry]);

  const radarData = useMemo(() => {
    if (!country) return [];
    return [
      { metric: 'Güç', A: country.power, fullMark: 10 },
      { metric: 'Etki', A: country.influence, fullMark: 10 },
      { metric: 'İstikrar', A: country.stability, fullMark: 10 },
      { metric: 'Risk', A: 10 - country.risk, fullMark: 10 },
      { metric: 'Ekonomi', A: Math.min(10, country.gdp / 3000), fullMark: 10 },
    ];
  }, [country]);

  if (!country)
    return (
      <div className="h-full flex items-center justify-center text-carbon-500 text-sm">
        <Radar className="w-8 h-8 mr-2 opacity-50" /> Ülke seçin
      </div>
    );

  return (
    <div className="h-full p-4">
      <h3 className="text-sm font-semibold text-carbon-100 mb-2 flex items-center gap-2">
        <Activity className="w-4 h-4 text-indigo-400" /> {country.name} Profili
      </h3>
      <ResponsiveContainer width="100%" height={250}>
        <RadarChart data={radarData}>
          <PolarGrid stroke="#334155" />
          <PolarAngleAxis dataKey="metric" tick={{ fill: '#94a3b8', fontSize: 11 }} />
          <PolarRadiusAxis angle={30} domain={[0, 10]} tick={{ fill: '#64748b', fontSize: 9 }} />
          <ReRadar
            name={country.name}
            dataKey="A"
            stroke="#6366f1"
            fill="#6366f1"
            fillOpacity={0.3}
          />
          <ReTooltip
            contentStyle={{ background: '#0f172a', border: '1px solid #334155', borderRadius: 0 }}
          />
        </RadarChart>
      </ResponsiveContainer>
      <div className="mt-4 space-y-2 text-xs text-carbon-300">
        <div className="flex justify-between border-b border-carbon-800 pb-1">
          <span>Blok</span>
          <span className="text-carbon-100 font-mono">{country.block}</span>
        </div>
        <div className="flex justify-between border-b border-carbon-800 pb-1">
          <span>GDP (M$)</span>
          <span className="text-carbon-100 font-mono">{country.gdp}</span>
        </div>
        <div className="flex justify-between border-b border-carbon-800 pb-1">
          <span>Risk Skoru</span>
          <span
            className={`font-mono ${country.risk > 7 ? 'text-red-400' : country.risk > 4 ? 'text-yellow-400' : 'text-green-400'}`}
          >
            {country.risk.toFixed(1)}
          </span>
        </div>
      </div>
    </div>
  );
};

// ─── NETWORK VIEW (FORCE-DIRECTED) ───────────────────────────────
const NetworkView = ({ data }: { data: BilateralSentimentData[] }) => {
  const { ref, containerRef } = useD3(
    (svg, w, h) => {
      const nodes = COUNTRIES.map((c) => ({
        id: c.id,
        name: c.name,
        block: c.block,
        power: c.power,
      }));
      const links = data.map((r) => ({
        source: r.from_country,
        target: r.to_country,
        value: Math.abs(r.affinity_score || 0),
        sentiment: r.affinity_score || 0,
        interactions: r.interaction_count || 0,
      }));

      const colorScale = d3
        .scaleOrdinal(d3.schemeCategory10)
        .domain(['WEST', 'EAST', 'ASIA', 'GLOBAL_SOUTH']);
      const affinityColor = d3.scaleSequential(d3.interpolateRdYlGn).domain([-1, 1]);

      const simulation = d3
        .forceSimulation(nodes as any)
        .force(
          'link',
          d3
            .forceLink(links as any)
            .id((d: any) => d.id)
            .distance(100),
        )
        .force('charge', d3.forceManyBody().strength(-300))
        .force('center', d3.forceCenter(w / 2, h / 2))
        .force(
          'collide',
          d3.forceCollide().radius((d: any) => 15 + d.power * 2),
        );

      const g = svg.append('g');

      // Zoom
      const zoom = d3.zoom().on('zoom', (event) => g.attr('transform', event.transform));
      svg.call(zoom as any);

      // Links
      const link = g
        .append('g')
        .selectAll('line')
        .data(links)
        .join('line')
        .attr('stroke', (d: any) => affinityColor(d.sentiment))
        .attr('stroke-width', (d: any) => Math.max(1, d.interactions / 30))
        .attr('stroke-opacity', 0.6);

      // Nodes
      const node = g
        .append('g')
        .selectAll('g')
        .data(nodes)
        .join('g')
        .call(
          d3
            .drag()
            .on('start', (event, d: any) => {
              if (!event.active) simulation.alphaTarget(0.3).restart();
              d.fx = d.x;
              d.fy = d.y;
            })
            .on('drag', (event, d: any) => {
              d.fx = event.x;
              d.fy = event.y;
            })
            .on('end', (event, d: any) => {
              if (!event.active) simulation.alphaTarget(0);
              d.fx = null;
              d.fy = null;
            }) as any,
        );

      node
        .append('circle')
        .attr('r', (d: any) => 6 + d.power)
        .attr('fill', (d: any) => colorScale(d.block))
        .attr('stroke', '#0f172a')
        .attr('stroke-width', 2)
        .style('cursor', 'pointer');

      node
        .append('text')
        .text((d: any) => d.id)
        .attr('x', (d: any) => 8 + d.power)
        .attr('y', 4)
        .attr('fill', '#cbd5e1')
        .attr('font-size', '9px')
        .attr('font-family', 'monospace');

      simulation.on('tick', () => {
        link
          .attr('x1', (d: any) => d.source.x)
          .attr('y1', (d: any) => d.source.y)
          .attr('x2', (d: any) => d.target.x)
          .attr('y2', (d: any) => d.target.y);
        node.attr('transform', (d: any) => `translate(${d.x},${d.y})`);
      });
    },
    [data],
  );

  return (
    <div
      ref={containerRef}
      className="w-full h-[500px] relative bg-carbon-950 rounded-none border border-carbon-700"
    >
      <svg ref={ref} className="w-full h-full" />
      <div className="absolute bottom-3 right-3 bg-carbon-900/90 border border-carbon-700 p-2 text-2xs text-carbon-300">
        <ZoomIn className="w-3 h-3 inline mr-1" /> Zoom için scroll
      </div>
    </div>
  );
};

// ─── MAIN COMPONENT ────────────────────────────────────────────────
type ViewMode = 'globe' | 'network' | 'chord' | 'heatmap' | 'radar';

export const BilateralRelations = () => {
  const toast = useToast();
  const [viewMode, setViewMode] = useState<ViewMode>('globe');
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [selectedPanel, setSelectedPanel] = useState<PanelTimelineEntry | null>(null);

  const dashboardQuery = useQuery({
    queryKey: ['bilateral-overview'],
    queryFn: () => apiClient.get<BilateralSentimentData[]>('/api/v1/dashboard/bilateral'),
    initialData: generateMockRelations(),
  });

  const timelineQuery = useQuery({
    queryKey: ['bilateral-timeline'],
    queryFn: () => apiClient.get<PanelTimelineEntry[]>('/api/v1/dashboard/bilateral/timeline'),
    initialData: generateTimeline(),
    staleTime: 1000 * 60 * 5,
  });

  const activeData = dashboardQuery.data || [];

  const stats = useMemo(() => {
    const avgAffinity = d3.mean(activeData, (d) => d.affinity_score || 0) || 0;
    const totalInteractions = d3.sum(activeData, (d) => d.interaction_count || 0);
    const avgRisk = d3.mean(activeData, (d) => (d as any).risk_score || 0) || 0;
    const positiveRelations = activeData.filter((d) => (d.affinity_score || 0) > 0.5).length;
    return {
      avgAffinity,
      totalInteractions,
      avgRisk,
      positiveRelations,
      totalCountries: COUNTRIES.length,
    };
  }, [activeData]);

  const handleCountrySelect = useCallback((id: string) => {
    setSelectedCountry((prev) => (prev === id ? null : id));
    setViewMode('radar');
  }, []);

  return (
    <div className="space-y-6 animate-[fade-in-up_300ms_ease-out_both]">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl font-semibold tracking-tight text-carbon-50 flex items-center gap-3">
            <Globe className="w-5 h-5 text-indigo-400" />
            Diplomatik İstihbarat Merkezi
          </h1>
          <p className="text-sm text-carbon-400 mt-1">
            İkili ilişkilerin çok boyutlu analizi: 3D küre projeksiyonu, Chord diagram, ısı haritası
            ve topluluk tespiti
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => dashboardQuery.refetch()}
            className="flex items-center gap-2 px-3 py-2 text-sm bg-carbon-800 border border-carbon-550 text-carbon-300 hover:text-carbon-100 hover:bg-carbon-700 transition-colors rounded-none"
          >
            <RefreshCw className="w-4 h-4" /> Yenile
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          {
            label: 'Ort. Affinity',
            value: stats.avgAffinity.toFixed(2),
            icon: Activity,
            color: stats.avgAffinity > 0 ? 'text-green-400' : 'text-red-400',
          },
          {
            label: 'Toplam Etkileşim',
            value: stats.totalInteractions.toLocaleString(),
            icon: GitCommit,
            color: 'text-blue-400',
          },
          {
            label: 'Ort. Risk',
            value: stats.avgRisk.toFixed(1),
            icon: BoxSelect,
            color: stats.avgRisk > 6 ? 'text-red-400' : 'text-yellow-400',
          },
          {
            label: 'Pozitif İlişki',
            value: `${stats.positiveRelations}`,
            icon: BarChart3,
            color: 'text-green-400',
          },
        ].map((stat, i) => (
          <motion.div
            key={stat.label}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.1 }}
            className="bg-carbon-900 border border-carbon-550 p-4 rounded-none"
          >
            <div className="flex items-center justify-between mb-2">
              <span className="text-2xs uppercase tracking-wider text-carbon-400 font-semibold">
                {stat.label}
              </span>
              <stat.icon className={`w-4 h-4 ${stat.color}`} />
            </div>
            <div className="text-2xl font-mono font-semibold text-carbon-50">{stat.value}</div>
          </motion.div>
        ))}
      </div>

      {/* View Mode Selector */}
      <div className="flex flex-wrap gap-2 border-b border-carbon-700 pb-3">
        {[
          { id: 'globe' as ViewMode, label: '3D Küre', icon: Globe },
          { id: 'network' as ViewMode, label: 'Ağ Analizi', icon: GitCommit },
          { id: 'chord' as ViewMode, label: 'Chord Matrisi', icon: ArrowRightLeft },
          { id: 'heatmap' as ViewMode, label: 'Zaman İzlemi', icon: Activity },
          { id: 'radar' as ViewMode, label: 'Ülke Profili', icon: Radar },
        ].map((mode) => (
          <button
            key={mode.id}
            onClick={() => setViewMode(mode.id)}
            className={`flex items-center gap-2 px-4 py-2 text-xs font-medium transition-all rounded-none border ${
              viewMode === mode.id
                ? 'bg-indigo-500/20 border-indigo-500/50 text-indigo-300'
                : 'bg-carbon-800 border-carbon-700 text-carbon-400 hover:text-carbon-200'
            }`}
          >
            <mode.icon className="w-3.5 h-3.5" /> {mode.label}
          </button>
        ))}
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <AnimatePresence mode="wait">
            <motion.div
              key={viewMode}
              initial={{ opacity: 0, scale: 0.98 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.98 }}
              transition={{ duration: 0.3 }}
            >
              {viewMode === 'globe' && (
                <GlobeView data={activeData} onSelect={handleCountrySelect} />
              )}
              {viewMode === 'network' && <NetworkView data={activeData} />}
              {viewMode === 'chord' && <ChordView data={activeData} />}
              {viewMode === 'heatmap' && <HeatmapView data={activeData} />}
              {viewMode === 'radar' && <RadarProfile selectedCountry={selectedCountry} />}
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Side Panel */}
        <div className="space-y-4">
          <div className="bg-carbon-900 border border-carbon-550 p-4 rounded-none">
            <h3 className="text-sm font-semibold text-carbon-50 mb-3 flex items-center gap-2">
              <Layers className="w-4 h-4 text-indigo-400" /> Zaman Çizelgesi
            </h3>
            <div className="space-y-2 max-h-[300px] overflow-y-auto">
              {timelineQuery.data?.map((panel, i) => (
                <button
                  key={panel.file_id}
                  onClick={() => setSelectedPanel(panel)}
                  className={`w-full text-left px-3 py-2 text-xs border transition-colors ${
                    selectedPanel?.file_id === panel.file_id
                      ? 'bg-indigo-500/10 border-indigo-500/30 text-indigo-300'
                      : 'bg-carbon-950 border-carbon-800 text-carbon-400 hover:border-carbon-600'
                  }`}
                >
                  <div className="font-medium">{panel.title}</div>
                  <div className="text-2xs text-carbon-500 mt-1">
                    {panel.date} • {panel.speaker_count} konuşmacı
                  </div>
                </button>
              ))}
            </div>
          </div>

          <div className="bg-carbon-900 border border-carbon-550 p-4 rounded-none">
            <h3 className="text-sm font-semibold text-carbon-50 mb-3 flex items-center gap-2">
              <Info className="w-4 h-4 text-indigo-400" /> Blok Dağılımı
            </h3>
            <div className="space-y-2">
              {['WEST', 'EAST', 'ASIA', 'GLOBAL_SOUTH'].map((block) => {
                const count = COUNTRIES.filter((c) => c.block === block).length;
                const pct = (count / COUNTRIES.length) * 100;
                return (
                  <div key={block} className="space-y-1">
                    <div className="flex justify-between text-xs text-carbon-300">
                      <span>{block}</span>
                      <span className="font-mono">{count}</span>
                    </div>
                    <div className="h-1.5 bg-carbon-800 rounded-none overflow-hidden">
                      <motion.div
                        className="h-full bg-indigo-500"
                        initial={{ width: 0 }}
                        animate={{ width: `${pct}%` }}
                        transition={{ duration: 0.8, delay: 0.2 }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {selectedCountry && (
            <motion.div
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              className="bg-carbon-900 border border-carbon-550 p-4 rounded-none"
            >
              <h3 className="text-sm font-semibold text-carbon-50 mb-2">Komşu Analizi</h3>
              <div className="space-y-1.5">
                {activeData
                  .filter(
                    (r) => r.from_country === selectedCountry || r.to_country === selectedCountry,
                  )
                  .sort((a, b) => Math.abs(b.affinity_score || 0) - Math.abs(a.affinity_score || 0))
                  .slice(0, 5)
                  .map((r, i) => {
                    const other =
                      r.from_country === selectedCountry ? r.to_country : r.from_country;
                    const c = COUNTRIES.find((x) => x.id === other);
                    return (
                      <div
                        key={i}
                        className="flex items-center justify-between text-xs py-1 border-b border-carbon-800 last:border-0"
                      >
                        <span className="text-carbon-300">{c?.name || other}</span>
                        <span
                          className={`font-mono ${(r.affinity_score || 0) > 0 ? 'text-green-400' : 'text-red-400'}`}
                        >
                          {(r.affinity_score || 0).toFixed(2)}
                        </span>
                      </div>
                    );
                  })}
              </div>
            </motion.div>
          )}
        </div>
      </div>
    </div>
  );
};
